31:/** Resumable workflow runner used by sign-in, consent, recovery, and profile migration. */
32:public final class WorkflowEngine {
33:    public enum Status {
34:        CREATED,
35:        RUNNING,
36:        WAITING,
37:        COMPLETED,
38:        FAILED,
39:        CANCELLED
40:    }
41:
42:    public enum StepStatus {
43:        PENDING,
44:        RUNNING,
45:        SUCCEEDED,
46:        FAILED,
47:        SKIPPED
48:    }
49:
50:    public interface Action {
51:        ActionResult execute(Context context) throws Exception;
52:
53:        default void compensate(Context context) throws Exception {
54:        }
55:    }
56:
57:    public interface Observer {
58:        void onTransition(String executionId, String stepId, StepStatus state);
59:    }
60:
61:    public static final class ActionResult {
62:        public final boolean success;
63:        public final boolean waiting;
64:        public final String code;
65:        public final Map<String, String> outputs;
66:
67:        private ActionResult(
68:                boolean success,
69:                boolean waiting,
70:                String code,
71:                Map<String, String> outputs) {
72:            this.success = success;
73:            this.waiting = waiting;
74:            this.code = code;
75:            this.outputs = Collections.unmodifiableMap(new LinkedHashMap<>(outputs));
76:        }
77:
78:        public static ActionResult success(Map<String, String> outputs) {
79:            return new ActionResult(true, false, "", outputs);
80:        }
81:
82:        public static ActionResult waiting(String code, Map<String, String> outputs) {
83:            return new ActionResult(false, true, require(code, "code"), outputs);
84:        }
85:
86:        public static ActionResult failure(String code) {
87:            return new ActionResult(false, false, require(code, "code"), Collections.emptyMap());
88:        }
89:    }
