91:    public static final class Step {
92:        public final String id;
93:        public final Set<String> dependencies;
94:        public final long timeoutMillis;
95:        public final boolean compensatable;
96:        public final Action action;
97:
98:        public Step(
99:                String id,
100:                Collection<String> dependencies,
101:                long timeoutMillis,
102:                boolean compensatable,
103:                Action action) {
104:            this.id = require(id, "id");
105:            this.dependencies = Collections.unmodifiableSet(
106:                    new LinkedHashSet<>(Objects.requireNonNull(dependencies, "dependencies")));
107:            this.timeoutMillis = timeoutMillis;
108:            this.compensatable = compensatable;
109:            this.action = Objects.requireNonNull(action, "action");
110:            if (timeoutMillis <= 0) {
111:                throw new IllegalArgumentException("timeoutMillis must be positive");
112:            }
113:        }
114:    }
