116:    public static final class Definition {
117:        public final String id;
118:        public final int revision;
119:        public final Map<String, Step> steps;
120:        private final List<String> order;
121:
122:        public Definition(String id, int revision, Collection<Step> steps) {
123:            this.id = require(id, "id");
124:            this.revision = revision;
125:            Map<String, Step> indexed = new LinkedHashMap<>();
126:            for (Step step : Objects.requireNonNull(steps, "steps")) {
127:                if (indexed.put(step.id, step) != null) {
128:                    throw new IllegalArgumentException("duplicate step: " + step.id);
129:                }
130:            }
131:            if (indexed.isEmpty()) {
132:                throw new IllegalArgumentException("workflow has no steps");
133:            }
134:            validateDependencies(indexed);
135:            this.order = topologicalOrder(indexed);
136:            this.steps = Collections.unmodifiableMap(indexed);
137:            if (revision <= 0) {
138:                throw new IllegalArgumentException("revision must be positive");
139:            }
140:        }
141:    }
