143:    public static final class Context {
144:        private final Map<String, String> values;
145:
146:        Context(Map<String, String> initial) {
147:            values = new LinkedHashMap<>(Objects.requireNonNull(initial, "initial"));
148:        }
149:
150:        public String get(String key) {
151:            return values.get(key);
152:        }
153:
154:        public String require(String key) {
155:            String value = values.get(key);
156:            if (value == null || value.trim().isEmpty()) {
157:                throw new IllegalStateException("missing workflow value: " + key);
158:            }
159:            return value;
160:        }
161:
162:        public void put(String key, String value) {
163:            values.put(
164:                    WorkflowEngine.require(key, "key"),
165:                    Objects.requireNonNull(value, "value"));
166:        }
167:
168:        public Map<String, String> snapshot() {
169:            return Collections.unmodifiableMap(new LinkedHashMap<>(values));
170:        }
171:    }
