173:    public static final class Execution {
174:        public final String id;
175:        public final Definition definition;
176:        public final Context context;
177:        private final Map<String, StepStatus> states = new LinkedHashMap<>();
178:        private final Deque<String> completed = new ArrayDeque<>();
179:        private Status status = Status.CREATED;
180:        private String waitingStep = "";
181:        private String errorCode = "";
182:
183:        Execution(String id, Definition definition, Map<String, String> input) {
184:            this.id = require(id, "id");
185:            this.definition = Objects.requireNonNull(definition, "definition");
186:            this.context = new Context(input);
187:            for (String stepId : definition.order) {
188:                states.put(stepId, StepStatus.PENDING);
189:            }
190:        }
191:
192:        public synchronized Status status() {
193:            return status;
194:        }
195:
196:        public synchronized String waitingStep() {
197:            return waitingStep;
198:        }
199:
200:        public synchronized String errorCode() {
201:            return errorCode;
202:        }
