209:    private final CockpitClock clock;
210:    private final List<Observer> observers = new ArrayList<>();
211:
212:    public WorkflowEngine(CockpitClock clock) {
213:        this.clock = Objects.requireNonNull(clock, "clock");
214:    }
215:
216:    public synchronized void addObserver(Observer observer) {
217:        observers.add(Objects.requireNonNull(observer, "observer"));
218:    }
