29:/** Owns session concurrency, expiry, zone transfer, and lifecycle notifications. */
30:public final class SessionSupervisor {
31:    public enum State {
32:        ACTIVE,
33:        IDLE,
34:        SUSPENDED,
35:        REAUTHENTICATION_REQUIRED,
36:        REVOKED,
