61:        public Limits(
62:                int maximumPerAccount,
63:                int maximumPerZone,
64:                long idleTimeoutMillis,
65:                long absoluteTimeoutMillis,
66:                long reauthenticationWindowMillis) {
67:            this.maximumPerAccount = maximumPerAccount;
68:            this.maximumPerZone = maximumPerZone;
69:            this.idleTimeoutMillis = idleTimeoutMillis;
70:            this.absoluteTimeoutMillis = absoluteTimeoutMillis;
71:            this.reauthenticationWindowMillis = reauthenticationWindowMillis;
72:            if (maximumPerAccount <= 0 || maximumPerZone <= 0) {
73:                throw new IllegalArgumentException("session maxima must be positive");
74:            }
75:            if (idleTimeoutMillis <= 0 || absoluteTimeoutMillis <= idleTimeoutMillis) {
76:                throw new IllegalArgumentException("invalid session timeouts");
