171:    public synchronized Session open(
172:            String sessionId,
173:            String accountId,
174:            int userId,
175:            String zone,
176:            long now) {
177:        if (sessions.containsKey(sessionId)) {
178:            throw new IllegalArgumentException("duplicate session: " + sessionId);
179:        }
180:        expire(now);
181:        enforceCapacity(accountId, zone);
182:        Session session = new Session(sessionId, accountId, userId, zone, now);
183:        sessions.put(sessionId, session);
184:        publish(EventType.OPENED, session, "", now);
185:        return session;
186:    }
