202:    public synchronized void transfer(String sessionId, String targetZone, long now) {
203:        Session session = requireActive(sessionId);
204:        String normalized = require(targetZone, "targetZone");
205:        if (!session.zone.equals(normalized)) {
206:            enforceZoneCapacity(normalized);
207:            synchronized (session) {
208:                session.zone = normalized;
209:                session.lastActiveAt = now;
210:            }
211:            publish(EventType.TRANSFERRED, session, "zone transfer", now);
212:        }
213:    }
