231:        Session session = requireExisting(sessionId);
232:        synchronized (session) {
233:            if (session.state != State.REAUTHENTICATION_REQUIRED
234:                    && session.state != State.SUSPENDED) {
235:                throw new IllegalStateException("session did not require reauthentication");
236:            }
237:            session.state = State.ACTIVE;
238:            session.authenticatedAt = now;
239:            session.lastActiveAt = now;
240:            session.reason = "";
241:        }
242:        publish(EventType.TOUCHED, session, "reauthenticated", now);
243:    }
244:
245:    public synchronized void revoke(String sessionId, String reason, long now) {
246:        Session session = requireExisting(sessionId);
247:        transition(session, State.REVOKED, require(reason, "reason"));
248:        publish(EventType.REVOKED, session, reason, now);
249:    }
250:
251:    public synchronized int expire(long now) {
252:        int expired = 0;
253:        for (Session session : sessions.values()) {
254:            synchronized (session) {
255:                if (terminal(session.state)) {
256:                    continue;
257:                }
258:                boolean absolute = now - session.openedAt >= limits.absoluteTimeoutMillis;
259:                boolean idle = now - session.lastActiveAt >= limits.idleTimeoutMillis;
260:                boolean staleAuthentication = session.state == State.REAUTHENTICATION_REQUIRED
261:                        && now - session.authenticatedAt >= limits.reauthenticationWindowMillis;
262:                if (absolute || idle || staleAuthentication) {
263:                    session.state = State.EXPIRED;
264:                    session.reason = absolute
265:                            ? "absolute timeout"
266:                            : staleAuthentication ? "reauthentication timeout" : "idle timeout";
267:                    publish(EventType.EXPIRED, session, session.reason, now);
268:                    expired++;
269:                } else if (now - session.lastActiveAt >= limits.idleTimeoutMillis / 2
270:                        && session.state == State.ACTIVE) {
271:                    session.state = State.IDLE;
272:                }
273:            }
274:        }
275:        return expired;
276:    }
277:
278:    public synchronized int removeTerminal() {
279:        int removed = 0;
280:        Iterator<Session> iterator = sessions.values().iterator();
281:        while (iterator.hasNext()) {
282:            if (terminal(iterator.next().state)) {
283:                iterator.remove();
284:                removed++;
285:            }
286:        }
287:        return removed;
288:    }
289:
290:    public synchronized List<Session> snapshot() {
291:        List<Session> values = new ArrayList<>(sessions.values());
292:        values.sort(Comparator.comparing((Session value) -> value.accountId)
293:                .thenComparing(value -> value.zone)
294:                .thenComparing(value -> value.id));
295:        return Collections.unmodifiableList(values);
296:    }
297:
298:    private void enforceCapacity(String accountId, String zone) {
299:        int accountCount = 0;
300:        for (Session session : sessions.values()) {
301:            if (!terminal(session.state) && session.accountId.equals(accountId)) {
302:                accountCount++;
303:            }
304:        }
305:        if (accountCount >= limits.maximumPerAccount) {
306:            throw new IllegalStateException("account session capacity reached");
307:        }
308:        enforceZoneCapacity(zone);
309:    }
310:
311:    private void enforceZoneCapacity(String zone) {
312:        int zoneCount = 0;
313:        for (Session session : sessions.values()) {
314:            if (!terminal(session.state) && session.zone.equals(zone)) {
315:                zoneCount++;
316:            }
317:        }
318:        if (zoneCount >= limits.maximumPerZone) {
319:            throw new IllegalStateException("zone session capacity reached");
320:        }
321:    }
322:
323:    private Session requireActive(String sessionId) {
324:        Session session = requireExisting(sessionId);
325:        if (terminal(session.state)) {
326:            throw new IllegalStateException("session is terminal");
327:        }
328:        return session;
329:    }
330:
331:    private Session requireExisting(String sessionId) {
332:        Session session = sessions.get(sessionId);
333:        if (session == null) {
334:            throw new IllegalArgumentException("unknown session: " + sessionId);
335:        }
336:        return session;
337:    }
338:
339:    private static void transition(Session session, State state, String reason) {
340:        synchronized (session) {
341:            session.state = state;
342:            session.reason = reason;
343:        }
344:    }
345:
346:    private void publish(EventType type, Session session, String reason, long timestamp) {
347:        Event event = new Event(type, session, reason, timestamp);
348:        for (Observer observer : new ArrayList<>(observers)) {
349:            observer.onEvent(event);
350:        }
351:    }
352:
353:    private static boolean terminal(State state) {
354:        return state == State.REVOKED || state == State.EXPIRED;
355:    }
356:
357:    private static String require(String value, String name) {
358:        Objects.requireNonNull(value, name);
359:        if (value.trim().isEmpty()) {
360:            throw new IllegalArgumentException(name + " must not be empty");
361:        }
362:        return value;
363:    }
364:}
